int findRotateSteps(char *ring, char *key) {
  int n = strlen(ring), m = strlen(key);
  int pos[26][n], posSize[26];
  memset(posSize, 0, sizeof(posSize));
  for (int i = 0; i < n; ++i) {
    int x = ring[i] - 'a';
    pos[x][posSize[x]++] = i;
  }
  int dp[m][n];
  memset(dp, 0x3f3f3f3f, sizeof(dp));
  for (int i = 0; i < posSize[key[0] - 'a']; i++) {
    int x = pos[key[0] - 'a'][i];
    dp[0][x] = fmin(x, n - x) + 1;
  }
  for (int i = 1; i < m; ++i) {
    for (int j = 0; j < posSize[key[i] - 'a']; ++j) {
      int x = pos[key[i] - 'a'][j];
      for (int k = 0; k < posSize[key[i - 1] - 'a']; ++k) {
        int y = pos[key[i - 1] - 'a'][k];
        dp[i][x] = fmin(dp[i][x], dp[i - 1][y] + fmin(abs(x - y), n - abs(x - y)) + 1);
      }
    }
  }
  int ret = dp[m - 1][0];
  for (int i = 1; i < n; ++i) {
    ret = fmin(ret, dp[m - 1][i]);
  }
  return ret;
}

class Solution {
public:
  int findRotateSteps(string ring, string key) {
    int n = ring.size(), m = key.size();
    vector<int> pos[26];
    for (int i = 0; i < n; ++i) {
      pos[ring[i] - 'a'].push_back(i);
    }
    int dp[m][n];
    memset(dp, 0x3f3f3f3f, sizeof(dp));
    for (auto &i : pos[key[0] - 'a']) {
      dp[0][i] = min(i, n - i) + 1;
    }
    for (int i = 1; i < m; ++i) {
      for (auto &j : pos[key[i] - 'a']) {
        for (auto &k : pos[key[i - 1] - 'a']) {
          dp[i][j] = min(dp[i][j], dp[i - 1][k] + min(abs(j - k), n - abs(j - k)) + 1);
        }
      }
    }
    return *min_element(dp[m - 1], dp[m - 1] + n);
  }
};

func findRotateSteps(ring string, key string) int {
	n, m := len(ring), len(key)
	pos := make([][]int, 26)
	for i := 0; i < n; i++ {
		pos[ring[i]-'a'] = append(pos[ring[i]-'a'], i)
	}
	const inf = 1 << 30
	dp := make([][]int, m)
	for i := range dp {
		dp[i] = make([]int, n)
		for j := range dp[i] {
			dp[i][j] = inf
		}
	}
	for _, i := range pos[key[0]-'a'] {
		dp[0][i] = min(i, n-i) + 1
	}
	for i := 1; i < m; i++ {
		for _, j := range pos[key[i]-'a'] {
			for _, k := range pos[key[i-1]-'a'] {
				d := j - k
				if d < 0 {
					d = -d
				}
				if n-d < d {
					d = n - d
				}
				if dp[i-1][k]+d+1 < dp[i][j] {
					dp[i][j] = dp[i-1][k] + d + 1
				}
			}
		}
	}
	res := inf
	for _, v := range dp[m-1] {
		if v < res {
			res = v
		}
	}
	return res
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

class Solution {
  public int findRotateSteps(String ring, String key) {
    int n = ring.length(), m = key.length();
    @SuppressWarnings("unchecked")
    ArrayList<Integer>[] pos = new ArrayList[26];
    for (int i = 0; i < 26; ++i) {
      pos[i] = new ArrayList<Integer>();
    }
    for (int i = 0; i < n; ++i) {
      pos[ring.charAt(i) - 'a'].add(i);
    }
    int[][] dp = new int[m][n];
    for (int i = 0; i < m; ++i) {
      Arrays.fill(dp[i], 0x3f3f3f);
    }
    for (int i : pos[key.charAt(0) - 'a']) {
      dp[0][i] = Math.min(i, n - i) + 1;
    }
    for (int i = 1; i < m; ++i) {
      for (int j : pos[key.charAt(i) - 'a']) {
        for (int k : pos[key.charAt(i - 1) - 'a']) {
          dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + Math.min(Math.abs(j - k), n - Math.abs(j - k)) + 1);
        }
      }
    }
    return Arrays.stream(dp[m - 1]).min().getAsInt();
  }
}

class Solution:
    def findRotateSteps(self, ring: str, key: str) -> int:
        n, m = len(ring), len(key)
        pos = {}
        for i, c in enumerate(ring):
            pos.setdefault(c, []).append(i)

        inf = float("inf")
        dp = [[inf] * n for _ in range(m)]
        for i in pos[key[0]]:
            dp[0][i] = min(i, n - i) + 1
        for i in range(1, m):
            for j in pos[key[i]]:
                for k in pos[key[i - 1]]:
                    d = abs(j - k)
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + min(d, n - d) + 1)
        return min(dp[m - 1])

impl Solution {
  pub fn find_rotate_steps(ring: String, key: String) -> i32 {
    let ring = ring.as_bytes();
    let key = key.as_bytes();
    let n = ring.len();
    let m = key.len();
    let mut pos: Vec<Vec<usize>> = vec![vec![]; 26];
    for (i, &c) in ring.iter().enumerate() {
      pos[(c - b'a') as usize].push(i);
    }
    let inf = i32::MAX / 2;
    let mut dp = vec![vec![inf; n]; m];
    for &i in &pos[(key[0] - b'a') as usize] {
      dp[0][i] = i.min(n - i) as i32 + 1;
    }
    for i in 1..m {
      for &j in &pos[(key[i] - b'a') as usize] {
        for &k in &pos[(key[i - 1] - b'a') as usize] {
          let d = (j as i32 - k as i32).abs();
          let step = d.min(n as i32 - d);
          dp[i][j] = dp[i][j].min(dp[i - 1][k] + step + 1);
        }
      }
    }
    *dp[m - 1].iter().min().unwrap()
  }
}

const findRotateSteps = (ring: string, key: string): number => {
  const n = ring.length;
  const m = key.length;
  const pos: Record<string, number[]> = {};
  for (let i = 0; i < n; i++) {
    const c = ring[i];
    (pos[c] ||= []).push(i);
  }
  const inf = Number.MAX_SAFE_INTEGER;
  const dp: number[][] = Array.from({ length: m }, () => new Array(n).fill(inf));
  for (const i of pos[key[0]]) dp[0][i] = Math.min(i, n - i) + 1;
  for (let i = 1; i < m; i++) {
    for (const j of pos[key[i]]) {
      for (const k of pos[key[i - 1]]) {
        const d = Math.abs(j - k);
        dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + Math.min(d, n - d) + 1);
      }
    }
  }
  return Math.min(...dp[m - 1]);
};
